refresh_update_details:
def refresh_update_details(self, widget=None, param=None):
    if self.labels['update_details'].get_expanded():
        self.labels['update_log'].get_buffer().set_text(self.update_log_text)
        self.scroll_update_details()

scroll_update_details:
def scroll_update_details(self, adjustment=None):
    if self.labels['update_details'].get_expanded():
        adjustment = self.labels['update_log_scroll'].get_vadjustment()
        adjustment.set_value(max(adjustment.get_lower(), adjustment.get_upper() - adjustment.get_page_size()))

stop_update_animation:
def stop_update_animation(self, *args):
    timer = getattr(self, 'update_animation_timer', None)
    if timer is not None:
        GLib.source_remove(timer)
        self.update_animation_timer = None
